const show=()=>`<section class="wrap pad" aria-labelledby="sh-h"><div class="g12"><div class="c8"><p class="kick">${esc(L.show.kick)}</p>${hl(L.show.h,'h2').replace('<h2','<h2 id="sh-h"')}<p class="lead-p">${esc(L.show.lead)}</p></div></div><div class="grid showgrid">${L.show.items.filter(i=>ART[i[2]]).map(i=>`<article class="card show"><div class="cardart">${ART[i[2]]}</div><div class="cb"><span class="scope">${esc(L.show.tag)}</span><h3>${esc(i[0])}</h3><p>${esc(i[1])}</p></div></article>`).join('')}</div><p class="note">${esc(L.show.note)}</p><p><a class="btn p" href="#/brief">${esc(L.cta.brief)}</a></p></section>`;
const home=()=>hero()+areas()+engage()+show()+cases()+pricing()+ready()+proof()+team()+leaders()+certs()+cta();
/* ---------- catalogue ---------- */
let F={q:'',g:'',sc:''};
const list=()=>{const q=F.q.trim().toLowerCase();return T.filter(t=>(!F.g||grOf(t).slug===F.g)&&(!F.sc||t.scope===F.sc)&&(!q||(t.name+' '+t.desc+' '+t.core.join(' ')+' '+grOf(t).name).toLowerCase().includes(q)))};
const grid=()=>{const r=list();return r.length?r.map(card).join(''):`<p>${esc(L.catalog.none)} <button type="button" class="btn" data-clearf>${esc(L.catalog.clear)}</button></p>`};
const cnt=()=>fill(L.catalog.count,{n:list().length,total:T.length});
const catalog=()=>`<section class="wrap pad tight hdrline"><div class="g12"><div class="c8"><p class="kick">${esc(L.catalog.kick)}</p><h1 class="h1s">${esc(L.catalog.h)}</h1><p class="lead-p">${esc(fill(L.catalog.lead,{n:T.length}))}</p></div></div><nav class="areanav" aria-label="${esc(L.catalog.area)}">${GR.map(g=>`<a class="chip" href="#/catalog/${g.slug}">${esc(g.name)}</a>`).join('')}</nav><div class="filters"><label>${esc(L.catalog.search)}<input id="q" type="search" value="${esc(F.q)}" placeholder="${esc(L.catalog.searchPh)}" autocomplete="off"></label><label>${esc(L.catalog.area)}<select id="fc"><option value="">${esc(L.catalog.allAreas)}</option>${GR.map(g=>`<option value="${g.slug}" ${F.g===g.slug?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><label>${esc(L.catalog.level)}<select id="fs"><option value="">${esc(L.catalog.allLevels)}</option>${Object.entries(L.scope).map(([k,v])=>`<option value="${k}" ${F.sc===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label></div><p class="note" id="cnt" role="status">${esc(cnt())}</p><p class="note">${esc(L.scopeNote)}</p><div class="grid" id="grid">${grid()}</div></section>`;
const groupPage=g=>`<section class="cat-hero ${lite()?'lite':''}" style="--c:${ACC[0]}">${lite()?'':`<canvas class="wc" data-i="${g.scene}" data-c="${ACC[0]}" aria-hidden="true"></canvas>`}<div class="wrap"><p><a class="tlink" href="#/catalog">${esc(L.catalog.back)}</a></p><h1 class="h1s">${esc(g.name)}</h1><p class="lead-p">${esc(g.promise)}</p><p class="note">${esc(g.line)}</p></div></section><section class="wrap pad tight"><div class="grid">${typesIn(g).map(card).join('')}</div></section>`;
