scrollTo(0,0);/* move focus to the page heading on navigation, but not on the very first load (keeps the skip link first in the tab order) */const h1=a.querySelector('h1');if(!firstLoad){if(h1){h1.tabIndex=-1;h1.focus({preventScroll:true})}else a.focus({preventScroll:true})}firstLoad=false;
document.querySelectorAll('.nav [data-r]').forEach(e=>{const on=e.dataset.r===p;e.classList.toggle('on',on);on?e.setAttribute('aria-current','page'):e.removeAttribute('aria-current')});mm(false);meta(ti,de,ld);upd();
